const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calc:'M5 3h14v18H5z M8 7h8 M8 12h1 M15 12h1 M8 16h1 M15 16h1',book:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',settings:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M5.6 5.6l2.1 2.1 M16.3 16.3l2.1 2.1 M5.6 18.4l2.1-2.1 M16.3 7.7l2.1-2.1 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]}"/></svg>`;
let participants=[],tab='people',query='',filter='',page=0,dirty=false,settings=normalizeAppSettings();
const nav=[['people','Participantes'],['calc','Calculadoras'],['book','Critérios e fontes'],['shield','Arquivos e segurança'],['settings','Configurações']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500);}
function render(){ $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-lockup"><img src="${brand}" alt="Hakunas"><small>LEGENDÁRIOS · TRIAGEM</small></div></div><nav class="nav" aria-label="Navegação principal">${nav.map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="side-bottom"><div class="local-note"><span class="dot"></span><strong>Seu dispositivo, seus dados.</strong><br>Participantes ficam nesta sessão. Salve um backup antes de sair.</div><div class="profile"><div class="avatar">EB</div><div><strong>Equipe de saúde</strong><br><small>Legendários Hakunas</small></div></div></div></aside><main class="main"><header class="topbar"><div><strong>Triagem Hakunas</strong> <span class="muted"> / ${nav.find(([id])=>id===tab)[1]}</span></div><div class="actions"><a class="download-link" href="./triagem-hakunas-offline.html" download="Triagem-Hakunas-Offline.html" ${location.protocol==='file:'?'hidden':''}>↓ Baixar HTML offline</a><span class="session-status"><span class="dot"></span>${location.protocol==='file:'?'HTML local · funciona sem internet':'Sessão local · sem sincronização'}</span></div></header><div class="content">${eventHeaderHTML(settings.header)}${tab==='people'?people():tab==='calc'?calculators():tab==='book'?sources():tab==='shield'?security():configuration()}<footer class="footer"><span>© ${new Date().getFullYear()} Dr. Edson Barroso dos Santos Júnior · LGND 203460<br>edson.barroso@gnail.com · @dredsonbarroso · www.dredsonbarroso.com.br</span><span>TRIAGEM HAKUNAS · V1.5<br>Apoio à avaliação profissional</span></footer></div></main></div>`;bind();}
function heading(k,title,sub,actions=''){return `<div class="eyebrow">LEGENDÁRIOS / ${k}</div><div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function people(){const results=participants.map(p=>({p,r:evaluate(p)})),complete=results.filter(x=>x.r.band).length,attention=results.filter(x=>x.r.exclusions.length||['red','black'].includes(x.r.color)).length;let list=results.filter(({p,r})=>(!query||`${participantLabel(p)} ${p.id} ${p.cpf||''} ${p.phone||''}`.toLowerCase().includes(query.toLowerCase()))&&(!filter||(filter==='pending'?!r.band:filter==='complete'?r.band:r.exclusions.length||['red','black'].includes(r.color))));page=Math.min(page,Math.max(0,Math.ceil(list.length/50)-1));return heading('GESTÃO DE PARTICIPANTES','Cuidar começa com conhecer.','Organize participantes e acompanhe cada etapa da avaliação.',`<button id="import">↥ Importar lista</button><button class="primary" id="new">＋ Novo participante</button>`)+`<section class="hero"><div><div class="eyebrow">PREPARAÇÃO COM PROPÓSITO</div><h2>Segurança em cada passo.</h2><p>Uma visão clara da saúde de cada participante.<br>Mais cuidado na preparação. Mais confiança na jornada.</p><span class="pill" style="background:#ffffff12;color:#d4dfc9">◈ ${esc(settings.event)}</span></div><div class="hero-badge"><img src="${brand}" alt="Hakunas" width="210"><br>CUIDAR · PREPARAR · SERVIR</div></section><div class="metrics">${[['Participantes',participants.length,'Pessoas cadastradas nesta sessão'],['Avaliações pendentes',participants.length-complete,'Aguardando revisão completa'],['Revisões completas',complete,'Com documentação conferida'],['Atenção prioritária',attention,'Alertas ou critérios de exclusão']].map(([l,n,s],i)=>`<div class="metric"><div class="metric-label">${l}<span class="metric-icon">${['◉','◷','✓','⚑'][i]}</span></div><strong>${n.toString().padStart(2,'0')}</strong><small>${s}</small></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Participantes</h2><small>Da inscrição à revisão, tudo em um só lugar.</small></div><div class="actions"><button class="small" id="backup">↓ Salvar backup</button><button class="small" id="reports">Salvar relatórios</button><button class="small" id="print-report">Imprimir relatório</button><button class="small" id="csv">Salvar CSV</button></div></div><div class="filters"><input class="search" id="search" aria-label="Buscar participantes" placeholder="⌕  Buscar nome, CPF ou telefone" value="${esc(query)}"><select id="filter" aria-label="Filtrar avaliações"><option value="">Todas as avaliações</option>${[['pending','Pendentes'],['complete','Revisões completas'],['attention','Atenção prioritária']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>PARTICIPANTE</th><th>IDADE / IMC</th><th>ATENÇÃO PROVISÓRIA</th><th>AVALIAÇÃO</th><th>AÇÕES</th></tr></thead><tbody>${list.length?list.slice(page*50,page*50+50).map(({p,r})=>`<tr><td><div class="person"><div class="avatar">${esc(isMissing(p.name)?'?':p.name.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div><strong>${esc(participantLabel(p))}</strong><small>${esc(p.phone||'Sem telefone informado')}</small></div></div></td><td>${esc(p.age||'—')} anos<br><small>IMC ${r.bmi?r.bmi.toFixed(1):'—'}</small></td><td><span class="pill ${r.color}">● ${({green:'Sem fator assinalado',yellow:'Amarelo',red:'Vermelho',black:'Preto'})[r.color]}</span></td><td>${r.band?`<span class="pill green">Revisão completa</span><br><small>Faixa interna: ${esc(r.band)}</small>`:`<span class="pending">◷ Revisão pendente</span><br><small>Parcial · ${r.score} pontos</small>`}</td><td><button class="small" data-edit="${p.id}">Abrir ficha</button></td></tr>`).join(''):`<tr><td colspan="5"><div class="empty"><div class="symbol">♧</div><h3>${participants.length?'Nenhum participante encontrado':'Sua próxima jornada começa aqui.'}</h3><p>${participants.length?'Ajuste a busca ou os filtros.':'Importe sua lista ou cadastre o primeiro participante para começar.'}</p>${!participants.length?'<button class="dark" id="empty-new">＋ Cadastrar participante</button>':''}</div></td></tr>`}</tbody></table></div><div class="panel-footer"><span>${list.length} participante(s) · Página ${page+1} de ${Math.max(1,Math.ceil(list.length/50))}</span><div class="actions"><button class="small" id="prev" ${page===0?'disabled':''}>←</button><button class="small" id="next" ${(page+1)*50>=list.length?'disabled':''}>→</button></div></div></section><div class="notice">ⓘ O score é uma regra operacional interna. Cores e pontuação não equivalem a diagnóstico ou autorização para atividade física. A decisão é do profissional responsável.</div>`;}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});const on=(s,f)=>{if($(s))$(s).onclick=f;};on('#new',()=>edit());on('#empty-new',()=>edit());on('#import',importDialog);on('#backup',backupDialog);on('#security-backup',backupDialog);on('#restore',restoreDialog);on('#csv',()=>reportDialog(false,'csv'));on('#reports',()=>reportDialog());on('#print-report',()=>reportDialog(true));on('#prev',()=>{page--;render();});on('#next',()=>{page++;render();});if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;page=0;render();};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(participants.find(p=>p.id===b.dataset.edit)));if($('#settings-form'))bindEventSettings();if($('#calc-form'))$('#calc-form').onsubmit=calcSubmit;on('#add-protocol',()=>{const title=$('#protocol-title').value.trim(),responsible=$('#protocol-owner').value.trim();if(!title||!responsible)return toast('Informe título e responsável / registro.');if(settings.protocols.length>=100)return toast('Limite de 100 referências. Exporte o backup antes de reorganizar.');settings.protocols.push({title,responsible,date:new Date().toISOString(),version:settings.protocols.length+1});dirty=true;render();});on('#clear',()=>{if(confirm('Apagar todos os participantes desta sessão? Esta ação não pode ser desfeita.')){participants=[];dirty=false;render();}});}
function modal(title,body){document.getElementById('print-sheet')?.remove();const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="ghost" id="close-modal" aria-label="Fechar">✕</button></div>${body}`;$('#close-modal').onclick=()=>d.close();if(!d.open)d.showModal();return d;}
function field(p,key,label){return `<label>${label}<${['notes','important','health','medical','medication','condition','allergy'].includes(key)?'textarea':'input'} name="${key}" maxlength="2000"  ${['age','weight','height'].includes(key)?'inputmode="decimal"':''} ${['notes','important','health','medical','medication','condition','allergy'].includes(key)?`>${esc(p[key])}</textarea>`:`value="${esc(p[key])}">`}</label>`;}
function select(p,k,label,options){return `<label>${label}<select name="${k}"><option value="">Não informado</option>${options.map(([v,l])=>`<option value="${v}" ${String(p[k])===v?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function edit(record){const p=record?JSON.parse(JSON.stringify(record)):{id:crypto.randomUUID(),flags:[],reviewed:[],reviewer:settings.reviewer};modal(record?'Ficha do participante':'Novo participante',`<form id="record-form"><div class="modal-body"><div class="notice">Dados mantidos somente nesta sessão. Salve um backup protegido antes de fechar ou atualizar.</div><div class="form-grid">${fields.map(([k,l])=>field(p,k,l)).join('')}</div>${p.sourceFields?.length?`<section class="section"><h3>Dados do arquivo original</h3><p><small>Campos e posições preservados. Valores abaixo não são diagnósticos confirmados.</small></p><details><summary>Conferir ${p.sourceFields.length} campo(s) de origem</summary><div class="source-fields">${p.sourceFields.map(f=>`<p><strong>${esc(f.label)}:</strong> ${esc(f.value)}<br><small>${esc(f.location)}</small></p>`).join('')}</div></details>${p.importWarnings?.length?`<div class="notice">${p.importWarnings.map(esc).join('<br>')}</div><label class="check"><input name="importReviewed" type="checkbox" ${p.importReviewed?'checked':''}>Conferi os avisos e os valores importados no documento original</label>`:''}</section>`:''}${Object.entries(groups).map(([group,items])=>`<section class="section"><h3>${({history:'Histórico médico',meds:'Medicamentos — fatores do manual',symptoms:'Sintomas atuais',exclusions:'Critérios de exclusão',extra:'Fatores adicionais'})[group]}</h3><div class="checks">${items.map(([id,l,score])=>`<label class="check"><input type="checkbox" name="flag" value="${id}" ${p.flags?.includes(id)?'checked':''}>${l}${score?` <small>+${score}</small>`:''}</label>`).join('')}</div><label class="check review"><input type="checkbox" name="reviewed" value="${group}" ${p.reviewed?.includes(group)?'checked':''}>Seção revisada com o participante / documentos</label></section>`).join('')}<section class="section"><h3>Preparação e revisão</h3><div class="form-grid">${select(p,'activity','Atividade física',[['0','3 ou mais vezes / semana'],['1','1–2 vezes / semana'],['2','Raramente'],['3','Não realiza']])}${select(p,'walk','Caminha 10 km sem fadiga excessiva?',[['0','Sim'],['1','Não tentou'],['2','Não']])}${select(p,'tetanus','Vacina antitetânica vigente?',[['0','Sim'],['1','Não / não sabe']])}${select(p,'prior','Já fez caminhadas longas?',[['0','Sim'],['1','Não']])}<label>Responsável e CRM<input name="reviewer" maxlength="200" value="${esc(p.reviewer)}"></label><label class="check"><input name="certificate" type="checkbox" ${p.certificate?'checked':''}>Atestado e exames obrigatórios conferidos</label></div></section><div id="record-result"></div><p class="error" id="record-error" role="alert"></p></div><div class="sticky"><div class="actions">${record?'<button type="button" class="danger" id="delete-record">Excluir</button>':''}<button type="button" id="print-record">Imprimir / PDF</button></div><button class="primary" type="submit">Salvar avaliação</button></div></form>`);const f=$('#record-form');const get=()=>{const d=new FormData(f);return{id:p.id,...(p.sourceFields?{sourceFields:p.sourceFields,importWarnings:p.importWarnings||[],importReviewed:d.has('importReviewed')}:{}),...Object.fromEntries(fields.map(([k])=>[k,isMissing(d.get(k))?'':String(d.get(k)).trim()])),flags:d.getAll('flag'),reviewed:d.getAll('reviewed'),activity:d.get('activity'),walk:d.get('walk'),tetanus:d.get('tetanus'),prior:d.get('prior'),reviewer:isMissing(d.get('reviewer'))?'':String(d.get('reviewer')).trim(),certificate:d.has('certificate')};};function preview(){try{$('#record-result').innerHTML=resultHTML(evaluate(get()));}catch{$('#record-result').innerHTML='<div class="notice">Confira as medidas para calcular.</div>';}}f.oninput=preview;preview();f.onsubmit=e=>{e.preventDefault();try{let next=validate(get());if(next.height)next.height=String(height(next.height));if(!record&&participants.length>=5000)throw Error('Limite de 5.000 participantes.');participants=record?participants.map(x=>x.id===p.id?next:x):[...participants,next];dirty=true;$('#modal').close();render();toast('Avaliação salva na sessão. Lembre-se do backup.');}catch(e){$('#record-error').textContent=e.message;}};$('#print-record').onclick=()=>{try{const current=get();validate(current);let print=document.getElementById('print-sheet');if(!print){print=document.createElement('div');print.id='print-sheet';document.body.append(print);}print.innerHTML=eventHeaderHTML(settings.header)+'<h1>Triagem Hakunas</h1><p>'+esc(new Date().toLocaleString('pt-BR'))+'</p><div class=print-fields>'+fields.map(([k,l])=>'<p><strong>'+esc(l)+':</strong> '+esc(current[k]||'Não informado')+'</p>').join('')+'</div><h2>Fatores assinalados</h2><p>'+Object.values(groups).flat().filter(([id])=>current.flags.includes(id)).map(([,l])=>esc(l)).join(' · ')+'</p>'+resultHTML(evaluate(current))+(current.sourceFields?.length?'<h2>Origem dos dados</h2>'+current.sourceFields.map(f=>'<p><strong>'+esc(f.label)+':</strong> '+esc(f.value)+'<br><small>'+esc(f.location)+'</small></p>').join(''):'')+'<p>Responsável / CRM: '+esc(current.reviewer||'Não informado')+'</p><p>Atestado e exames conferidos: '+(current.certificate?'Sim':'Não')+'</p>';window.print();}catch(e){$('#record-error').textContent=e.message;}};if($('#delete-record'))$('#delete-record').onclick=()=>{if(confirm('Excluir este participante da sessão?')){participants=participants.filter(x=>x.id!==p.id);dirty=true;$('#modal').close();render();}};}
function resultHTML(r){return `<div class="result"><strong>${r.band?'Faixa interna: '+r.band:'Parcial — faixa final não calculável'}</strong><p>Score interno: <strong>${r.score}</strong> · IMC adulto: ${r.bmi?r.bmi.toFixed(1):'não calculável / não aplicável'}</p><p>Atenção operacional provisória: <span class="pill ${r.color}">${({green:'Sem fator assinalado',yellow:'Amarelo',red:'Vermelho',black:'Preto'})[r.color]}</span></p>${r.reasons.map(esc).join(' · ')}${r.components.length?`<details><summary>Componentes da pontuação</summary><ul>${r.components.map(c=>`<li>${esc(c.label)}: +${c.points}</li>`).join('')}</ul></details>`:''}${r.exclusions.length?`<p class="error"><strong>Critérios de exclusão — revisão obrigatória:</strong><br>${r.exclusions.map(esc).join('<br>')}</p>`:''}${r.pending.length?`<details open><summary>Pendências (${r.pending.length})</summary><ul>${r.pending.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`:''}<small>Não diagnostica nem libera participação. Exclusões prevalecem sobre a soma; a decisão exige avaliação profissional.</small></div>`;}
async function importDialog(){const d=modal('Importar arquivos — leitura local',`<div class="modal-body stack"><div class="notice">Excel/ODS, CSV/TSV/TXT, HTML/XML/JSON, DOCX/ODT, PDF e imagens comuns. O arquivo é lido neste dispositivo. Cabeçalhos podem estar em qualquer linha/coluna; fichas podem estar em blocos ou transpostas. Confira os blocos detectados antes de incluir registros.</div><label class="check"><input id="use-ocr" type="checkbox">Usar OCR local em páginas de PDF sem texto (mais lento; até 10 páginas)</label><label>Escolha o arquivo<input id="import-file" type="file" accept=".xlsx,.xls,.xlsm,.xlsb,.ods,.csv,.tsv,.txt,.html,.htm,.xml,.json,.docx,.docm,.dotx,.odt,.pdf,.png,.jpg,.jpeg,.webp,.bmp,.gif"></label><p id="import-status" role="status"></p><div id="import-controls"></div><div id="mapping"></div><div id="import-preview"></div><p class="error" id="import-error" role="alert"></p></div>`);let sheets=[],layouts=[],active=0,head=0,preview=null,revision=0,busy=false;const error=e=>{if($('#import-error'))$('#import-error').textContent=e.message;};const invalidate=()=>{preview=null;if($('#import-preview'))$('#import-preview').innerHTML='';};const clearError=()=>{if($('#import-error'))$('#import-error').textContent='';};d.addEventListener('close',()=>{revision++;import('./ocr.js').then(m=>m.stopOCR()).catch(()=>{});},{once:true});
function showPreview(result){preview=result;clearError();if(preview.participants.length+participants.length>5000)throw Error('A sessão excederia 5.000 participantes.');const names=preview.participants.filter(p=>!isMissing(p.name)).map(p=>p.name.toLowerCase().trim()),duplicateNames=names.length-new Set(names).size,withMissing=preview.participants.filter(p=>missingFields(p).length).length,grouped=warningGroups(preview.warnings),checked=preview.identifierChecks||{verified:0,needsReview:0};$('#import-preview').innerHTML=`<section class="import-summary" aria-label="Resumo da prévia"><strong>Prévia pronta: ${preview.participants.length} participante(s)</strong><p>Nenhum participante foi incluído ainda. As avaliações clínicas continuam pendentes.</p><p>Campos vazios foram ignorados no processamento. ${withMissing} registro(s) com dados não informados serão listados nos relatórios, sem interromper os demais.</p>${checked.verified?`<p class="identifier-checks">✓ ${checked.verified} campo(s) de CPF/telefone com estrutura conferida automaticamente neste dispositivo.</p>`:''}<p><small>A conferência verifica formato/dígitos, não titularidade, cadastro oficial ou existência do telefone.</small></p>${duplicateNames?`<p class="error">${duplicateNames} nome(s) repetido(s). Confira se selecionou blocos duplicados; não mesclamos registros automaticamente.</p>`:''}${preview.warnings.length?`<details class="import-warnings"><summary>${preview.warnings.length} aviso(s) de conferência · ver ${grouped.length} tipo(s)</summary><div class="warning-list">${grouped.map(g=>`<div class="warning-group"><strong>${g.count} ocorrência(s)</strong><p>${esc(g.reason)}</p>${g.locations.length?`<small>Exemplos de origem: ${g.locations.map(esc).join(' · ')}</small>`:''}</div>`).join('')}</div><p><small>Os detalhes de cada registro ficam na ficha. Esses avisos permitem inclusão com revisão pendente; erros bloqueantes impedem o conjunto inteiro.</small></p></details>`:'<p class="identifier-checks">✓ Nenhum aviso de importação detectado. A revisão clínica continua necessária.</p>'}</section><div class="table-scroll"><table class="import-preview-table"><thead><tr><th>Nome</th><th>Idade</th><th>Altura</th><th>Campos</th></tr></thead><tbody>${preview.participants.slice(0,5).map(p=>`<tr><td>${esc(participantLabel(p))}</td><td>${esc(p.age||'—')}</td><td>${esc(p.height||'—')}</td><td>${p.sourceFields?.length||0}</td></tr>`).join('')}</tbody></table></div><p class="import-help"><small>Prévia de até 5 registros. Campos não vazios são preservados com sua origem. Campos vazios não confirmam ausência de doença.</small></p><div class="import-confirmation"><label class="check"><input id="confirm-source-review" type="checkbox"><span>Conferi os blocos e a prévia. Entendo que dados clínicos e avisos ainda precisam ser revisados nas fichas.</span></label><button class="primary" id="confirm-import" ${preview.participants.length?'':'disabled'}>Confirmar inclusão de ${preview.participants.length} participantes</button><small>Passo final: marque a caixa acima e toque no botão. Isto inclui na sessão; use o backup para salvar em arquivo.</small></div>`;$('#confirm-import').onclick=()=>{if(!$('#confirm-source-review').checked)return toast('Confira a prévia e assinale a confirmação.');participants.push(...preview.participants);dirty=true;d.close();render();toast('Importação concluída. Confira os dados e avisos em cada ficha.');};}
function drawManual(){invalidate();const rows=sheets[active].rows;if(head>=rows.length)head=0;const map=mapping(rows[head]||[]);$('#mapping').innerHTML=`<section class="section stack"><h3>Mapeamento manual — preserva posições do arquivo</h3><div class="grid"><label>Aba / tabela<select id="sheet">${sheets.map((s,i)=>`<option value="${i}" ${i===active?'selected':''}>${esc(s.name)} (${s.rows.length} linhas)</option>`).join('')}</select></label><label>Linha do cabeçalho<input id="header-row" type="number" min="1" max="${rows.length}" value="${head+1}"></label><label>Primeira linha de dados<input id="first-data" type="number" min="1" max="${rows.length}" value="${head+2}"></label><label>Última linha de dados<input id="last-data" type="number" min="1" max="${rows.length}" value="${rows.length}"></label></div>${(rows[head]||[]).map((h,i)=>`<label>Coluna ${i+1} · ${esc(h||'Sem rótulo')}<select data-map="${i}"><option value="">Preservar como campo de origem</option>${[...fields,...Object.values(groups).flat().map(([k,l])=>['flag:'+k,'Resposta explícita: '+l])].map(([k,l])=>`<option value="${k}" ${map[i]===k?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`).join('')}<button id="make-preview">Conferir prévia</button></section>`;$('#sheet').onchange=e=>{active=+e.target.value;head=0;drawManual();};$('#header-row').onchange=e=>{head=Math.max(0,Math.min(rows.length-1,+e.target.value-1));drawManual();};document.querySelectorAll('[data-map],#first-data,#last-data').forEach(el=>el.onchange=invalidate);$('#make-preview').onclick=()=>{try{const first=+$('#first-data').value-1,last=+$('#last-data').value;if(first<=head||last<=first||last>rows.length)throw Error('Escolha um intervalo de dados após o cabeçalho.');const map=[...document.querySelectorAll('[data-map]')].map(x=>x.value);if(new Set(map.filter(Boolean)).size!==map.filter(Boolean).length)throw Error('Um campo não pode ser mapeado duas vezes.');if(!map.some(Boolean))throw Error('Mapeie ao menos um campo de dados.');const records=[];for(let r=first;r<last;r++){if(!rows[r].some(v=>String(v??'').trim()))continue;if(mapping(rows[r]).includes('name'))continue;records.push({cells:rows[r].map((value,c)=>({key:map[c]||'',label:String(rows[head][c]||'Coluna '+(c+1)),value:String(value??''),declared:!!String(rows[head][c]||'').trim(),location:sourceAddress(sheets[active],r,c),...sourceCellMetadata(sheets[active],r,c)}))});}showPreview(recordsToPreview(records,{ocr:sheets[active].ocr}));}catch(e){invalidate();error(e);}};}
function drawAuto(){invalidate();$('#mapping').innerHTML=layouts.length?`<section class="section stack"><h3>${layouts.length} estrutura(s) detectada(s)</h3><p class="muted">Selecione as tabelas e blocos que deseja importar. A mesma pessoa em abas diferentes pode representar registros repetidos.</p>${layouts.map((l,i)=>`<label class="check"><input type="checkbox" data-layout="${i}" checked><span><strong>${esc(l.sheetName)} · ${esc(l.kind)}</strong><br><small>${esc(l.range)} · ${l.records.length} registro(s) · ${l.recognized} campo(s) reconhecido(s)</small></span></label>`).join('')}<button id="make-preview">Conferir prévia</button></section>`:`<div class="notice">Não encontrei uma estrutura com rótulos suficientes para leitura automática. Nenhum dado foi adicionado. Use o mapeamento manual ou corrija o texto com rótulos como “Nome:”, “Idade:” e “Altura:”.</div>`;document.querySelectorAll('[data-layout]').forEach(el=>el.onchange=invalidate);if($('#make-preview'))$('#make-preview').onclick=()=>{try{const selected=[...document.querySelectorAll('[data-layout]:checked')].map(e=>layouts[+e.dataset.layout]);if(!selected.length)throw Error('Selecione ao menos uma estrutura.');const records=selected.flatMap(l=>l.records.map(rec=>({cells:rec.cells.map(cell=>({...cell,...sourceCellMetadata(sheets[l.sheetIndex],cell.row,cell.col)}))})));showPreview(recordsToPreview(records,{ocr:selected.some(l=>sheets[l.sheetIndex].ocr)}));}catch(e){invalidate();error(e);}};}
function controls(){layouts=detectLayouts(sheets);active=Math.max(0,sheets.findIndex(s=>s.rows.length));head=0;for(let i=0,best=0;i<sheets[active].rows.length;i++){const n=mapping(sheets[active].rows[i]).filter(Boolean).length;if(n>best){best=n;head=i;}}$('#import-controls').innerHTML=`<div class="actions"><button id="auto-mode" class="dark">Detectar estruturas</button><button id="manual-mode">Mapear colunas manualmente</button></div><details class="section"><summary>Conferir / corrigir texto extraído</summary><p><small>OCR pode trocar caracteres e números. Corrija localmente o texto e reanalise. A correção não altera o arquivo original. Para planilhas, use o mapeamento manual.</small></p><textarea id="source-text" maxlength="2097152" rows="10" aria-label="Texto extraído">${esc(sheets.extractedText||'')}</textarea><p><button id="reanalyze-text">Reanalisar texto corrigido</button></p></details>`;$('#auto-mode').onclick=drawAuto;$('#manual-mode').onclick=drawManual;$('#reanalyze-text').onclick=()=>{try{const text=$('#source-text').value;if(!text.trim())throw Error('Informe o texto com rótulos antes de reanalisar.');const wasOCR=sheets.usedOCR;sheets=Object.assign(textToSheets(text,'Texto conferido'),{extractedText:text,usedOCR:wasOCR});sheets.forEach(s=>s.ocr=wasOCR);clearError();controls();}catch(e){error(e);}};drawAuto();if(layouts.length===1)$('#make-preview')?.click();}
$('#import-file').onchange=async e=>{if(busy)return;const file=e.target.files[0];if(!file)return;busy=true;e.target.disabled=true;const token=++revision;try{clearError();invalidate();$('#mapping').innerHTML='';$('#import-controls').innerHTML='';sheets=await readFile(file,{ocr:$('#use-ocr').checked,onProgress:text=>{if(token===revision&&$('#import-status'))$('#import-status').textContent=text;}});if(token!==revision)return;controls();$('#import-status').textContent=`Leitura concluída: ${sheets.length} aba(s)/tabela(s). ${sheets.usedOCR?'OCR local utilizado: confira o documento original.':''}`;}catch(e){if(token===revision){error(e);if($('#import-status'))$('#import-status').textContent='Nenhum registro adicionado.';}}finally{busy=false;if($('#import-file'))$('#import-file').disabled=false;}};
}

function download(content,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backupDialog(){modal('Salvar backup protegido',`<form id="backup-form"><div class="modal-body stack"><p>${participants.length} participante(s) e configurações serão incluídos. A senha não é armazenada e não pode ser recuperada.</p><label>Senha (mínimo de 10 caracteres)<input type="password" id="password" minlength="10" required autocomplete="new-password"></label><label>Confirme a senha<input type="password" id="password-confirm" minlength="10" required autocomplete="new-password"></label><p class="error" id="backup-error" role="alert"></p><button class="primary">Salvar arquivo .LGND</button></div></form>`);$('#backup-form').onsubmit=async e=>{e.preventDefault();try{if($('#password').value!==$('#password-confirm').value)throw Error('As senhas não coincidem.');let data=await encrypt({schema:2,participants,settings},$('#password').value);download(data,'triagem-hakunas-'+eventFileTag(settings.header)+'-'+new Date().toLocaleDateString('sv-SE',{timeZone:'America/Sao_Paulo'})+'.LGND');dirty=false;$('#modal').close();toast('Backup gerado. Confira o arquivo na pasta de downloads.');}catch(e){$('#backup-error').textContent=e.message;}};}
function restoreDialog(){modal('Restaurar backup',`<form id="restore-form"><div class="modal-body stack"><p>A restauração substitui a sessão atual somente depois da validação e da sua confirmação.</p><label>Arquivo .LGND<input type="file" id="restore-file" accept=".LGND" required></label><label>Senha<input type="password" id="restore-password" minlength="10" required autocomplete="current-password"></label><p class="error" id="restore-error" role="alert"></p><button class="primary">Validar e restaurar</button></div></form>`);$('#restore-form').onsubmit=async e=>{e.preventDefault();try{let f=$('#restore-file').files[0];if(f.size>45*1024*1024)throw Error('Backup muito grande.');let data=await decrypt(await f.text(),$('#restore-password').value),next=validateBackup(data);const nextSettings=normalizeAppSettings(data.settings);if(!confirm(`Substituir esta sessão por ${next.length} participante(s) do backup, incluindo sua identificação de TOP?`))return;participants=next;settings=nextSettings;dirty=false;$('#modal').close();render();toast('Backup restaurado.');}catch(e){$('#restore-error').textContent=e.message;}};}
function security(){return heading('SESSÃO E PROTEÇÃO','Arquivos e segurança','Controle seus dados com arquivos locais protegidos.')+`<div class="grid"><section class="panel pad"><h2>Backup criptografado</h2><p class="muted">Preserve todas as fichas e configurações em um arquivo .LGND protegido por senha.</p><p><small>AES-GCM 256 bits · PBKDF2-SHA256 · 310.000 iterações · salt e IV aleatórios.</small></p><button class="primary" id="security-backup">↓ Salvar arquivo protegido</button></section><section class="panel pad"><h2>Retomar uma sessão</h2><p class="muted">Selecione seu backup e informe a senha. A sessão será substituída após sua confirmação.</p><p><small>Sem recuperação de senha. Guarde a senha separada do arquivo.</small></p><button id="restore">↥ Restaurar backup</button></section></div><section class="panel pad"><h2>Como seus dados são tratados</h2><div class="stack"><p>As fichas ficam na memória desta aba. Atualizar ou fechar o navegador pode apagar os dados. Não há banco, login, sincronização, telemetria ou envio automático.</p><p>CSV e impressão são legíveis. Proteja os arquivos e escolha um local adequado para armazená-los. Para enviar um backup à nuvem, faça o upload manualmente no serviço de sua preferência.</p><div><button class="danger" id="clear">Apagar participantes da sessão</button></div></div></section>`;}
function sources(){return heading('TRANSPARÊNCIA','Critérios e fontes','Conheça a origem de cada regra e os limites de uso.')+`<section class="panel pad"><h2>Score interno Hakunas</h2><p>Transcrição dos itens do manual Hakunas, versão 1.0, datado de 7 de dezembro de 2025. Pontuação operacional interna, sem validação clínica externa demonstrada.</p><div class="table-scroll"><table><thead><tr><th>Faixa</th><th>Pontos</th></tr></thead><tbody><tr><td>Baixa</td><td>0–7</td></tr><tr><td>Moderada</td><td>8–15</td></tr><tr><td>Alta</td><td>16–25</td></tr><tr><td>Muito alta</td><td>26 ou mais</td></tr></tbody></table></div><p class="notice">As faixas só aparecem após revisão completa. A pontuação não libera participação e não cancela critérios de exclusão. Menores de 18 não recebem faixa adulta.</p>${Object.entries(groups).filter(([k])=>k!=='extra').map(([k,items])=>`<details class="section"><summary>${({history:'Histórico',meds:'Medicamentos',symptoms:'Sintomas',exclusions:'Exclusões'})[k]}</summary><ul>${items.map(([,l,n])=>`<li>${esc(l)}${n?' · +'+n:''}</li>`).join('')}</ul></details>`).join('')}<p>Também pontuam IMC > 30 (+2), frequência de atividade (0–3), caminhada (0–2), vacina antitetânica (0–1) e caminhadas prévias (0–1). IMC > 40, anticoagulantes, doença aguda e incapacidade de caminhar 10 km são exclusões independentes.</p></section><section class="panel pad"><h2>Cores operacionais provisórias</h2><p>Origem: regras descritas no relatório consolidado de 10/11/2026, separadas da tabela do manual. Amarelo: IMC > 30 ou medicamentos. Vermelho: doença explicitamente marcada, hipertensão, diabetes, idade > 60 ou limitação cirúrgica. Preto: convulsão ou idade > 60 associada a doença. A divergência vermelho/preto para implantes exige revisão.</p><p>Regra operacional definida pelo responsável: idades inteiras de 16–17 anos recebem vermelho, sem IMC ou faixa adulta final. Preto exige outro critério preto explícito; a menoridade isolada não o determina. Campos vazios não comprovam ausência de doença.</p></section><section class="panel pad"><h2>Instrumentos externos</h2><p>IMC e CKD-EPI são calculados separadamente. Não alteram a ficha automaticamente.</p><p><a href="https://www.niddk.nih.gov/research-funding/research-programs/kidney-clinical-research-epidemiology/laboratory/glomerular-filtration-rate-equations/adults" target="_blank" rel="noopener noreferrer">NIDDK — equações de TFGe em adultos</a></p><p><a href="https://eparmedx.com/" target="_blank" rel="noopener noreferrer">PAR-Q+ oficial</a> — formulário externo; não reproduzido no aplicativo.</p><p><small>Framingham, KFRE e rastreio ACSM citados no relatório anterior ainda não estão implementados nesta versão.</small></p></section>`;}
function calculators(){return heading('FERRAMENTAS INDEPENDENTES','Calculadoras','Resultados separados da pontuação e da ficha do participante.')+`<section class="panel pad"><form id="calc-form" class="stack"><div class="grid"><label>Ferramenta<select name="tool" id="tool"><option value="bmi">IMC — índice de massa corporal</option><option value="egfr">TFGe — CKD-EPI 2021</option></select></label><label>Idade (anos)<input name="age" type="number" min="1" max="120" required></label><label>Peso (kg) · IMC<input name="weight" inputmode="decimal"></label><label>Altura (cm ou m) · IMC<input name="height" inputmode="decimal"></label><label>Creatinina (mg/dL) · TFGe<input name="creatinine" inputmode="decimal"></label><label>Sexo usado na equação · TFGe<select name="sex"><option value="">Selecione</option><option value="female">Feminino</option><option value="male">Masculino</option></select></label></div><div><button class="primary">Calcular</button></div><div id="calc-result" role="status"></div></form></section><div class="notice">IMC em menores: apenas a razão numérica, sem classificação adulta. CKD-EPI 2021: adultos, creatinina padronizada, sem raça. A estimativa isolada não diagnostica DRC nem serve para decisões em função renal instável. Nenhum resultado estima risco agudo em trilha.</div>`;}
function calcSubmit(e){e.preventDefault();let d=new FormData(e.target),n=k=>Number(String(d.get(k)).replace(',','.'));try{let age=n('age');if(!Number.isInteger(age)||age<1||age>120)throw Error('Idade inválida.');let text;if(d.get('tool')==='bmi'){let h=height(d.get('height')),w=n('weight');if(!h||w<20||w>350)throw Error('Informe peso (20–350 kg) e altura válidos.');let b=w/(h/100)**2;text=`IMC: ${b.toFixed(2)} kg/m². `+(age<18?'Sem classificação adulta. Requer avaliação por idade e sexo.':b<18.5?'Baixo peso.':b<25?'Faixa de referência adulta.':b<30?'Sobrepeso.':'Obesidade.');}else{let cr=n('creatinine'),sex=d.get('sex');if(age<18||!['female','male'].includes(sex)||cr<0.1||cr>30)throw Error('TFGe: informe idade adulta, sexo e creatinina de 0,1 a 30 mg/dL.');let f=sex==='female',k=f?.7:.9,a=f?-.241:-.302;let g=142*Math.min(cr/k,1)**a*Math.max(cr/k,1)**-1.2*.9938**age*(f?1.012:1);text=`TFGe estimada: ${g.toFixed(1)} mL/min/1,73 m² (CKD-EPI 2021). Não é diagnóstico isolado de DRC.`;}$('#calc-result').innerHTML=`<div class="calc-result">${esc(text)}</div>`;}catch(e){$('#calc-result').innerHTML=`<p class="error">${esc(e.message)}</p>`;}}
function configuration(){const h=normalizeEventHeader(settings.header),pending=headerPending(h);return heading('IDENTIFICAÇÃO DO EVENTO','Configurações do TOP','Monte o cabeçalho de cada TOP e confira a prévia antes de salvar.')+`<section class="panel pad"><form id="settings-form" class="stack"><h2>Identificação do TOP</h2><div class="form-grid"><label>Número do TOP<input id="top-number" name="topNumber" inputmode="numeric" pattern="[0-9]{1,8}" maxlength="8" placeholder="Digite o número" value="${esc(h.topNumber)}"></label><label>Local<input name="location" maxlength="160" placeholder="Cidade / local do TOP" value="${esc(h.location)}"></label><label>Nome da base<input name="baseName" maxlength="100" placeholder="Nome da base" value="${esc(h.baseName)}"></label></div><div class="header-logo-controls"><div class="stack"><label>Logo da base — lado esquerdo<input id="base-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG ou WebP local, até 5 MiB. A imagem será preparada no dispositivo.</small></label><label>Fundo da logo da base<select name="baseLogoBackground"><option value="light" ${h.baseLogoBackground==='light'?'selected':''}>Claro</option><option value="dark" ${h.baseLogoBackground==='dark'?'selected':''}>Escuro</option></select></label><div><button type="button" class="small" id="remove-base-logo">Remover logo da base</button></div></div><div class="stack"><label>Logo dos Legendários — lado direito<input id="legend-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><small>Selecione a logo correta. Nenhum emblema é inventado ou buscado na internet.</small></label><label>Fundo da logo dos Legendários<select name="legendLogoBackground"><option value="light" ${h.legendLogoBackground==='light'?'selected':''}>Claro</option><option value="dark" ${h.legendLogoBackground==='dark'?'selected':''}>Escuro</option></select></label><div><button type="button" class="small" id="remove-legend-logo">Remover logo dos Legendários</button></div></div></div><div class="header-preview"><h3>Prévia do cabeçalho</h3><div id="header-preview">${eventHeaderHTML(h)}</div></div><div class="header-pending" id="header-pending">${pending.length?'Ainda não informado: '+pending.map(esc).join(' · '):'Identificação e dois emblemas preenchidos.'}</div><p class="muted"><small>Fonte Anton incorporada, semelhante ao estilo de letras altas e fortes da referência. É uma aproximação; não é identificação da fonte exata da imagem. O número digitado, inclusive zeros iniciais, é preservado.</small></p><div class="grid"><label>Nome da operação / pista<input name="event" maxlength="200" value="${esc(settings.event)}"></label><label>Responsável padrão e CRM<input name="reviewer" maxlength="200" value="${esc(settings.reviewer)}"></label></div><p class="error" id="header-error" role="alert"></p><p id="header-status" role="status"></p><div class="header-actions"><button class="primary" id="save-header" type="submit">Salvar identificação do TOP</button><button id="new-top" type="button">Iniciar outro TOP</button></div><small>Salvar mantém a configuração na sessão. Para conservar número, local, logos e registros, gere o backup protegido. Iniciar outro TOP não deve reaproveitar registros do TOP anterior sem uma decisão explícita.</small></form></section><section class="panel pad"><h2>Registro de referências</h2><p class="muted">Registrar referência não arquiva o documento nem modifica a pontuação.</p><div class="grid"><label>Título e versão do documento<input id="protocol-title" maxlength="200"></label><label>Responsável e registro profissional<input id="protocol-owner" maxlength="200"></label></div><p><button id="add-protocol">Adicionar referência</button></p>${settings.protocols.map(p=>`<div class="section"><strong>${esc(p.title)}</strong><p>${esc(p.responsible)} · Registro ${esc(p.version||'não informado')} · ${esc(p.date?new Date(p.date).toLocaleDateString('pt-BR'):'Data não informada')}</p></div>`).join('')}</section>`;}
function bindEventSettings(){const form=$('#settings-form');let draft=normalizeEventHeader(settings.header),pendingImages=0;const getDraft=()=>{const d=new FormData(form);return normalizeEventHeader({...draft,topNumber:String(d.get('topNumber')||''),location:String(d.get('location')||''),baseName:String(d.get('baseName')||''),baseLogoBackground:String(d.get('baseLogoBackground')),legendLogoBackground:String(d.get('legendLogoBackground'))});};const preview=()=>{try{draft=getDraft();$('#header-preview').innerHTML=eventHeaderHTML(draft);const missing=headerPending(draft);$('#header-pending').textContent=missing.length?'Ainda não informado: '+missing.join(' · '):'Identificação e dois emblemas preenchidos.';$('#header-error').textContent='';}catch(e){$('#header-error').textContent=e.message;}};form.oninput=preview;form.querySelectorAll('select').forEach(el=>el.onchange=preview);for(const[id,key]of[['base-logo-file','baseLogo'],['legend-logo-file','legendLogo']]){const input=$('#'+id);input.onchange=async()=>{if(!input.files[0])return;pendingImages++;$('#save-header').disabled=true;$('#header-status').textContent='Preparando emblema localmente…';try{const data=await logoFileToDataURL(input.files[0]);if(!form.isConnected)return;draft[key]=data;preview();$('#header-status').textContent='Emblema preparado no dispositivo. Salve a identificação para aplicar.';}catch(e){if(form.isConnected){$('#header-error').textContent=e.message;$('#header-status').textContent='O emblema anterior foi preservado.';}}finally{pendingImages--;if(form.isConnected)$('#save-header').disabled=pendingImages>0;}};}for(const[id,key,file]of[['remove-base-logo','baseLogo','base-logo-file'],['remove-legend-logo','legendLogo','legend-logo-file']])$('#'+id).onclick=()=>{draft[key]='';$('#'+file).value='';preview();};form.onsubmit=e=>{e.preventDefault();try{if(pendingImages)throw Error('Aguarde a preparação do emblema.');const h=getDraft(),old=normalizeEventHeader(settings.header);if(participants.length&&old.topNumber&&h.topNumber!==old.topNumber&&!confirm(`Esta ação corrigirá o TOP de todos os ${participants.length} registros carregados. Se é outro evento, cancele, salve um backup e use “Iniciar outro TOP”. Corrigir a identificação desta sessão?`))return;const d=new FormData(form);settings=normalizeAppSettings({event:String(d.get('event')||'').trim(),reviewer:String(d.get('reviewer')||'').trim(),protocols:settings.protocols,header:h});dirty=true;render();toast('Identificação do TOP salva na sessão. Salve o backup para conservar.');}catch(e){$('#header-error').textContent=e.message;}};$('#new-top').onclick=newTopDialog;}
function newTopDialog(){const count=participants.length;modal('Iniciar outra sessão de TOP',`<div class="modal-body stack"><p>A sessão atual contém <strong>${count} registro(s)</strong>. O novo TOP começará sem esses registros. Nome da base e logos serão mantidos como ponto de partida; número e local serão limpos para você preencher. O nome da operação volta ao padrão.</p><div class="notice">Se precisa conservar a sessão atual, salve o backup antes. Não há recuperação automática de registros apagados da memória.</div><button id="backup-before-new-top" type="button">Salvar backup da sessão atual</button><label class="check"><input id="confirm-new-top" type="checkbox"><span>Entendo que os registros atuais sairão desta sessão e que preciso guardar o backup para retomá-los.</span></label><button class="primary" id="start-new-top" type="button">Iniciar nova sessão vazia</button><p class="error" id="new-top-error" role="alert"></p></div>`);$('#backup-before-new-top').onclick=backupDialog;$('#start-new-top').onclick=()=>{if(!$('#confirm-new-top').checked){$('#new-top-error').textContent='Confirme que entende a troca de sessão.';return;}const old=normalizeEventHeader(settings.header);participants=[];settings={...settings,event:'Operação Hakunas',header:normalizeEventHeader({...old,topNumber:'',location:''})};query='';filter='';page=0;dirty=true;$('#modal').close();render();toast('Nova sessão vazia. Preencha número e local antes de identificar o novo TOP.');};}

window.addEventListener('afterprint',()=>document.getElementById('print-sheet')?.remove());
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
const headerStyle=document.createElement('style');headerStyle.id='event-header-style';headerStyle.textContent=eventHeaderCSS;document.head.append(headerStyle);
render();
if(!globalThis.__HAKUNAS_STANDALONE__&&'serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));

function reportDialog(printFirst=false,initialFormat='html'){
 if(!participants.length)return toast('Inclua registros na sessão para gerar os relatórios.');
 const snapshot=JSON.parse(JSON.stringify(participants)),model=reportModel(snapshot,{event:settings.event,date:new Date(),header:normalizeEventHeader(settings.header)});
 const incomplete=model.entries.filter(e=>e.missing.length);
 modal('Salvar ou imprimir relatórios',`<div class="modal-body stack"><p><strong>${snapshot.length} registro(s) da sessão inteira.</strong> Filtros e paginação não limitam os arquivos. Edições ainda não salvas na ficha não são incluídas.</p>
 <div class="notice" id="report-missing-alert" role="status">${incomplete.length?`<strong>${incomplete.length} participante(s) com campos não preenchidos.</strong> Isto é um alerta: não impede salvar ou imprimir.<details><summary>Ver qual participante e quais campos</summary><ul>${incomplete.map(({p,missing})=>`<li><strong>${esc(participantLabel(p))}</strong> · ID ${esc(p.id)}: ${missing.map(f=>esc(f.label)+' — não preenchido').join('; ')}.</li>`).join('')}</ul></details>`:'Nenhum campo de cadastro/preparação não preenchido detectado.'}</div>
 <label>Extensão do arquivo<select id="report-format">${Object.entries(reportFormats).map(([key,value])=>`<option value="${key}" ${key===initialFormat?'selected':''}>${esc(value.label)}</option>`).join('')}</select></label>
 <label>Onde salvar<select id="report-destination"><option value="choose">Escolher pasta e nome (se disponível)</option><option value="download">Baixar pelo navegador</option><option value="share">Compartilhar arquivo / escolher Drive</option></select></label>
 <p id="report-destination-help"><small>${typeof globalThis.showSaveFilePicker==='function'?'O seletor do sistema permite escolher pasta e nome. Se o Drive estiver integrado a ele, você poderá escolhê-lo.':'Este navegador não oferece seletor de pasta ao app. O download segue as configurações do navegador; ative “Perguntar onde salvar” se houver. No celular, Compartilhar pode oferecer o Drive instalado; você escolhe a conta e a pasta no Drive.'} O aplicativo não faz upload automático nem confirma gravação no Drive. Se estiver offline, a sincronização do Drive depende dele e da conexão posterior.</small></p>
 <p><small>PDF e HTML incluem os emblemas e o cabeçalho de impressão. XLSX, ODS e CSV incluem TOP, local e base como dados; CSV contém um conjunto único com identificação e campos. Todos incluem ausências sem inventar valores. Os arquivos são legíveis e não substituem o backup criptografado .LGND.</small></p>
 <label class="check"><input id="report-readable-consent" type="checkbox"><span>Entendo que estes arquivos contêm dados pessoais/de saúde legíveis e escolho onde guardá-los.</span></label>
 <button class="primary" id="report-complete">Salvar relatório completo</button><button id="report-missing">Salvar dados faltantes</button>
 <button id="report-print">Imprimir relatório completo</button><button id="report-print-missing">Imprimir dados faltantes</button>
 <p class="error" id="report-error" role="alert"></p><p id="report-status" role="status"></p></div>`);
 const buttons=['#report-complete','#report-missing','#report-print','#report-print-missing'].map(id=>$(id));
 const statusEl=$('#report-status'),errorEl=$('#report-error'),consentEl=$('#report-readable-consent'),formatEl=$('#report-format'),destinationEl=$('#report-destination');
 const execute=async(kind,printing=false)=>{
  if(!consentEl.checked)return toast('Confirme que entende que os relatórios são legíveis.');
  const setBusy=value=>buttons.forEach(button=>{button.disabled=value;});
  setBusy(true);errorEl.textContent='';statusEl.textContent=printing?'Preparando impressão…':'Preparando arquivo…';
  try{
   const format=formatEl.value;
   if(printing){const html=kind==='full'?fullReportHTML(model):exportReport(model,'missing','html').data;await printReportHTML(html);statusEl.textContent='Impressão solicitada ao navegador. Escolha a impressora ou Salvar como PDF; o app não confirma a impressão física.';}
   else{
    const info=reportFileInfo(model,kind,format),destination=destinationEl.value;
    const result=await saveExport(info,()=>exportReport(model,kind,format).data,destination);
    statusEl.textContent=result.method==='cancelled'?'Operação cancelada; nenhum salvamento foi concluído.':result.method==='picker'?`Arquivo gravado: ${result.name}.`:result.method==='share'?`Arquivo entregue ao compartilhamento: ${result.name}. Confira o destino escolhido; o app não confirma gravação no Drive.`:`Download solicitado: ${result.name}. Confira a pasta definida pelo navegador; o app não confirma que o download terminou.`;
   }
  }catch(e){errorEl.textContent=e.message+' Se o seletor não estiver disponível, escolha Baixar pelo navegador; para o Drive, envie o arquivo pelo aplicativo Drive.';statusEl.textContent='O app não confirmou salvamento.';}
  finally{setBusy(false);}
 };
 $('#report-complete').onclick=()=>execute('full');$('#report-missing').onclick=()=>execute('missing');$('#report-print').onclick=()=>execute('full',true);$('#report-print-missing').onclick=()=>execute('missing',true);
 if(printFirst){statusEl.textContent='Confira os alertas, assinale a ciência dos dados e toque em Imprimir relatório completo.';$('#report-print').focus();}
}
